package com.shop.engagement.controller;
import com.shop.common.response.*;import com.shop.common.security.*;import com.shop.engagement.dto.*;import com.shop.engagement.service.ProductEngagementService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/merchant/product-engagement") @RequiredArgsConstructor public class MerchantProductEngagementController {private final ProductEngagementService service;private Long m(){return CurrentUserHolder.get().getMerchantId();}
 @GetMapping("/questions") @RequirePermission("merchant:engagement:manage") public ApiResult<PageResult<EngagementVO.Question>> questions(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size){return ApiResult.success(service.questions(m(),page,size));}
 @PostMapping("/questions/{id}/answer") @RequirePermission("merchant:engagement:manage") public ApiResult<Void> answer(@PathVariable Long id,@Valid @RequestBody EngagementRequests.Answer r){service.answer(m(),CurrentUserHolder.get().getUserId(),id,r);return ApiResult.success();}
 @PostMapping("/questions/{id}/hide") @RequirePermission("merchant:engagement:manage") public ApiResult<Void> hideQ(@PathVariable Long id,@RequestBody(required=false) EngagementRequests.Hide r){service.hideQuestion(m(),id,r==null?new EngagementRequests.Hide():r);return ApiResult.success();}
 @PostMapping("/reviews/{id}/hide") @RequirePermission("merchant:engagement:manage") public ApiResult<Void> hideR(@PathVariable Long id,@RequestBody(required=false) EngagementRequests.Hide r){service.hideReview(m(),id,r==null?new EngagementRequests.Hide():r);return ApiResult.success();}}
